<template>
  <main class="min-vh-100 bg-body-tertiary py-5"><div class="container" style="max-width:760px"><div class="text-center mb-4"><div class="text-success fs-1"><i class="bi bi-capsule-pill"></i></div><h3 class="fw-bold">MediStore Customer Portal</h3><p class="text-muted">Your orders, invoices and pharmacy account</p></div>
    <div v-if="!token" class="card border-0 shadow-sm"><div class="card-body p-4"><h5 class="mb-3">{{activating?'Activate your account':'Customer sign in'}}</h5><form v-if="!activating" @submit.prevent="login"><label class="form-label">Registered phone number</label><input v-model="form.phone" class="form-control mb-3" required placeholder="03xxxxxxxxx"><label class="form-label">Password</label><input v-model="form.password" type="password" class="form-control mb-3" required><button class="btn btn-success w-100" :disabled="busy">{{busy?'Please wait…':'Sign in'}}</button></form><form v-else @submit.prevent="redeem"><label class="form-label">Invitation token</label><input v-model="activation.invitation_token" class="form-control mb-3" required><label class="form-label">Create password</label><input v-model="activation.password" type="password" minlength="10" class="form-control mb-3" required><label class="form-label">Confirm password</label><input v-model="activation.password_confirmation" type="password" minlength="10" class="form-control mb-3" required><button class="btn btn-success w-100">Activate account</button></form><button class="btn btn-link btn-sm px-0 mt-2" @click="activating=!activating">{{activating?'Back to sign in':'Have an invitation? Activate account'}}</button><div class="small text-muted mt-2">Invitations expire after 24 hours. Ask your pharmacy if you need a new invitation.</div></div></div>
    <template v-else><div class="d-flex justify-content-between align-items-center mb-3"><div><h5 class="mb-0">Welcome, {{dashboard.customer?.name}}</h5><div class="small text-muted">{{dashboard.customer?.phone}}</div></div><button class="btn btn-outline-secondary btn-sm" @click="logout">Sign out</button></div><div class="row g-3 mb-3"><div class="col-6"><div class="card border-0 shadow-sm"><div class="card-body"><div class="small text-muted">Account balance</div><h4 class="mb-0">Rs {{money(dashboard.customer?.balance)}}</h4></div></div></div><div class="col-6"><div class="card border-0 shadow-sm"><div class="card-body"><div class="small text-muted">Loyalty points</div><h4 class="mb-0">{{dashboard.customer?.loyalty_points||0}}</h4></div></div></div></div><div class="card border-0 shadow-sm mb-3"><div class="card-header bg-white fw-semibold">My online orders</div><div v-for="o in orders" :key="o.id" class="p-3 border-bottom d-flex justify-content-between"><div><strong>{{o.order_no}}</strong><div class="small text-muted">{{o.created_at}}</div></div><div class="text-end"><span class="badge text-bg-light text-capitalize">{{o.status}}</span><div class="small mt-1">Rs {{money(o.total)}}</div></div></div><div v-if="!orders.length" class="p-3 text-muted small">No online orders yet.</div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">My invoices</div><div v-for="i in invoices" :key="i.id" class="p-3 border-bottom d-flex justify-content-between align-items-center"><div><strong>{{i.invoice_no}}</strong><div class="small text-muted">{{i.sale_date}}</div></div><div class="text-end"><div>Rs {{money(i.total)}}</div><span class="badge text-bg-light">{{i.payment_status}}</span><div><button class="btn btn-sm btn-outline-success mt-2" @click="openReturn(i.id)">Request return</button></div></div></div><div v-if="!invoices.length" class="p-3 text-muted small">No invoices available.</div></div>
      <div class="card border-0 shadow-sm mt-3"><div class="card-header bg-white fw-semibold">My return requests</div><div v-for="r in returnRequests" :key="r.id" class="p-3 border-bottom d-flex justify-content-between"><div><strong>{{r.request_no}}</strong><div class="small text-muted">{{r.invoice_no}} · {{r.reason}}</div></div><span class="badge text-bg-light text-capitalize">{{r.status}}</span></div><div v-if="!returnRequests.length" class="p-3 text-muted small">No return requests yet.</div></div>
      <div v-if="selectedInvoice" class="card border-success mt-3"><div class="card-header bg-white d-flex justify-content-between"><strong>Request return · {{selectedInvoice.invoice_no}}</strong><button class="btn-close" @click="selectedInvoice=null"></button></div><div class="card-body"><div class="small text-muted mb-2">Select the quantity you want the pharmacy to review. Approval is required; this does not automatically refund or restock an item.</div><div v-for="line in selectedInvoice.items" :key="line.id" class="row align-items-center g-2 py-2 border-bottom"><div class="col"><div class="fw-semibold">{{line.medicine_name}}</div><div class="small text-muted">Sold {{line.quantity}} · Already returned {{line.returned_qty}}</div></div><div class="col-auto"><input v-model.number="returnQuantities[line.id]" type="number" min="0" :max="line.quantity-line.returned_qty" class="form-control form-control-sm" style="width:90px" :disabled="line.quantity-line.returned_qty<=0"></div></div><label class="form-label mt-3">Reason</label><select v-model="returnReason" class="form-select mb-2"><option value="">Select reason</option><option>Wrong item delivered</option><option>Damaged packaging</option><option>Incorrect quantity</option><option>Other</option></select><textarea v-model="returnNote" class="form-control mb-3" rows="2" placeholder="Additional details (optional)"></textarea><button class="btn btn-success" :disabled="returnBusy" @click="submitReturnRequest">{{returnBusy?'Submitting…':'Submit return request'}}</button></div></div></template>
    <div v-if="notice" class="alert alert-success mt-3">{{notice}}</div><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><div class="text-center text-muted small mt-4">For medicine advice or prescription questions, contact your pharmacist directly.</div>
  </div></main>
</template>
<script setup>
import { onMounted,ref } from 'vue';import axios from 'axios';
const base='/api/customer-portal',token=ref(sessionStorage.getItem('customer_portal_token')||''),busy=ref(false),error=ref(''),activating=ref(false),form=ref({phone:'',password:''}),activation=ref({invitation_token:'',password:'',password_confirmation:''}),dashboard=ref({}),orders=ref([]),invoices=ref([]),returnRequests=ref([]),selectedInvoice=ref(null),returnQuantities=ref({}),returnReason=ref(''),returnNote=ref(''),returnBusy=ref(false),notice=ref('');
const client=()=>axios.create({baseURL:base,headers:token.value?{Authorization:`Bearer ${token.value}`}:{}});
const money=v=>Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function redeem(){busy.value=true;error.value='';try{await axios.post(`${base}/redeem-invitation`,activation.value);activation.value={invitation_token:'',password:'',password_confirmation:''};activating.value=false;error.value='Account activated. Please sign in.'}catch(e){error.value=e.response?.data?.message||'Unable to activate account.'}finally{busy.value=false}}
async function login(){busy.value=true;error.value='';notice.value='';try{const r=await axios.post(`${base}/login`,form.value);token.value=r.data.token;sessionStorage.setItem('customer_portal_token',token.value);await load()}catch(e){error.value=e.response?.data?.message||'Unable to sign in.'}finally{busy.value=false}}
async function load(){try{const c=client();const [d,o,i,rr]=await Promise.all([c.get('/dashboard'),c.get('/orders'),c.get('/invoices'),c.get('/return-requests')]);dashboard.value=d.data;orders.value=o.data.data||[];invoices.value=i.data.data||[];returnRequests.value=rr.data.data||[]}catch(e){if(e.response?.status===401)logout();else error.value='Unable to load your account.'}}
async function logout(){try{if(token.value)await client().post('/logout')}catch{}token.value='';sessionStorage.removeItem('customer_portal_token');dashboard.value={};orders.value=[];invoices.value=[];returnRequests.value=[];selectedInvoice.value=null}
async function openReturn(id){error.value='';notice.value='';try{const r=await client().get(`/invoices/${id}`);selectedInvoice.value=r.data;returnQuantities.value={};returnReason.value='';returnNote.value=''}catch(e){error.value='Unable to load invoice details.'}}
async function submitReturnRequest(){const items=Object.entries(returnQuantities.value).filter(([,q])=>Number(q)>0).map(([sale_item_id,quantity])=>({sale_item_id:Number(sale_item_id),quantity:Number(quantity)}));if(!items.length||!returnReason.value){error.value='Select at least one item and a return reason.';return}returnBusy.value=true;try{await client().post('/return-requests',{sale_id:selectedInvoice.value.id,reason:returnReason.value,customer_note:returnNote.value,items});selectedInvoice.value=null;notice.value='Return request submitted. Your pharmacy will review it.';await load()}catch(e){error.value=e.response?.data?.message||'Unable to submit return request.'}finally{returnBusy.value=false}}
onMounted(()=>{if(token.value)load()});
</script>
